package com.nthexperience.desktop;

import android.database.*;
import android.os.*;
import android.provider.*;
import java.io.*;

/** A real, read-only test provider. It is absent from the production APK. */
public final class FixtureDocumentsProvider extends DocumentsProvider {
    private static final String[] ROOTS={DocumentsContract.Root.COLUMN_ROOT_ID,DocumentsContract.Root.COLUMN_DOCUMENT_ID,DocumentsContract.Root.COLUMN_TITLE,DocumentsContract.Root.COLUMN_FLAGS,DocumentsContract.Root.COLUMN_MIME_TYPES};
    private static final String[] DOCS={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_FLAGS,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED};
    @Override public boolean onCreate(){try{try(FileOutputStream stream=new FileOutputStream(new File(getContext().getCacheDir(),"chapter.txt"))){stream.write("A real document opened through a granted folder.".getBytes(java.nio.charset.StandardCharsets.UTF_8));}}catch(IOException ex){return false;}return true;}
    @Override public Cursor queryRoots(String[] projection){MatrixCursor cursor=new MatrixCursor(projection==null?ROOTS:projection);MatrixCursor.RowBuilder row=cursor.newRow();put(cursor,row,DocumentsContract.Root.COLUMN_ROOT_ID,"nth-fixture");put(cursor,row,DocumentsContract.Root.COLUMN_DOCUMENT_ID,"root");put(cursor,row,DocumentsContract.Root.COLUMN_TITLE,"Nth Test Storage");put(cursor,row,DocumentsContract.Root.COLUMN_FLAGS,DocumentsContract.Root.FLAG_SUPPORTS_IS_CHILD|DocumentsContract.Root.FLAG_LOCAL_ONLY);put(cursor,row,DocumentsContract.Root.COLUMN_MIME_TYPES,"*/*");return cursor;}
    @Override public Cursor queryDocument(String id,String[] projection){MatrixCursor cursor=new MatrixCursor(projection==null?DOCS:projection);document(cursor,id);return cursor;}
    @Override public Cursor queryChildDocuments(String parent,String[] projection,String sort){MatrixCursor cursor=new MatrixCursor(projection==null?DOCS:projection);if(parent.equals("root"))document(cursor,"archive");if(parent.equals("archive")){document(cursor,"nested");document(cursor,"chapter");}if(parent.equals("nested"))document(cursor,"readme");return cursor;}
    private void document(MatrixCursor cursor,String id){boolean directory=id.equals("root")||id.equals("archive")||id.equals("nested");String name=id.equals("root")?"Test storage":id.equals("archive")?"Archive":id.equals("nested")?"Nested":id.equals("chapter")?"Chapter.txt":"Readme.txt";MatrixCursor.RowBuilder row=cursor.newRow();put(cursor,row,DocumentsContract.Document.COLUMN_DOCUMENT_ID,id);put(cursor,row,DocumentsContract.Document.COLUMN_DISPLAY_NAME,name);put(cursor,row,DocumentsContract.Document.COLUMN_MIME_TYPE,directory?DocumentsContract.Document.MIME_TYPE_DIR:"text/plain");put(cursor,row,DocumentsContract.Document.COLUMN_FLAGS,0);put(cursor,row,DocumentsContract.Document.COLUMN_SIZE,directory?null:47);put(cursor,row,DocumentsContract.Document.COLUMN_LAST_MODIFIED,1700000000000L);}
    private void put(MatrixCursor cursor,MatrixCursor.RowBuilder row,String column,Object value){if(cursor.getColumnIndex(column)>=0)row.add(column,value);}
    @Override public boolean isChildDocument(String parent,String child){return parent.equals("root")&&!child.equals("root")||parent.equals("archive")&&(child.equals("nested")||child.equals("chapter")||child.equals("readme"))||parent.equals("nested")&&child.equals("readme");}
    @Override public DocumentsContract.Path findDocumentPath(String parent,String child) throws FileNotFoundException {java.util.ArrayList<String> path=new java.util.ArrayList<>();path.add("root");if(!child.equals("root"))path.add("archive");if(child.equals("nested")||child.equals("readme"))path.add("nested");if(child.equals("chapter")||child.equals("readme"))path.add(child);if(parent!=null){int start=path.indexOf(parent);if(start<0)throw new FileNotFoundException();path=new java.util.ArrayList<>(path.subList(start,path.size()));}return new DocumentsContract.Path(parent==null?"nth-fixture":null,path);}
    @Override public ParcelFileDescriptor openDocument(String id,String mode,CancellationSignal signal) throws FileNotFoundException {if(!mode.equals("r")||!id.equals("chapter")&&!id.equals("readme"))throw new FileNotFoundException();return ParcelFileDescriptor.open(new File(getContext().getCacheDir(),"chapter.txt"),ParcelFileDescriptor.MODE_READ_ONLY);}
}
